import{_ as r,C as a,c as o,o as l,aj as s,G as i,w as u}from"./chunks/framework.Bfdr4H5E.js";const w=JSON.parse('{"title":"Trading Plan – Explanatory Notes","description":"","frontmatter":{"outline":"deep","prev":{"text":"Trading Plan Template","link":"/trading-with-pav/trading-plan-template"},"next":{"text":"Procedures Manual","link":"/trading-with-pav/procedures-manual"}},"headers":[],"relativePath":"trading-with-pav/trading-plan-explanatory-notes.md","filePath":"trading-with-pav/trading-plan-explanatory-notes.md"}'),d={name:"trading-with-pav/trading-plan-explanatory-notes.md"};function c(h,e,p,g,m,y){const n=a("GraphComment"),t=a("ClientOnly");return l(),o("div",null,[e[0]||(e[0]=s('<h1 id="trading-plan-–-explanatory-notes" tabindex="-1">Trading Plan – Explanatory Notes <a class="header-anchor" href="#trading-plan-–-explanatory-notes" aria-label="Permalink to &quot;Trading Plan – Explanatory Notes&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#trading-plan-–-explanatory-notes-1">Trading Plan – Explanatory Notes</a><ul><li><a href="#cover-page">Cover Page</a></li><li><a href="#preface">Preface</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#the-trader">The Trader</a></li><li><a href="#the-trading-business">The Trading Business</a></li><li><a href="#the-trading-process">The Trading Process</a></li><li><a href="#annexes">Annexes</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="trading-plan-–-explanatory-notes-1" tabindex="-1">Trading Plan – Explanatory Notes <a class="header-anchor" href="#trading-plan-–-explanatory-notes-1" aria-label="Permalink to &quot;Trading Plan – Explanatory Notes&quot;">​</a></h2><h3 id="cover-page" tabindex="-1">Cover Page <a class="header-anchor" href="#cover-page" aria-label="Permalink to &quot;Cover Page&quot;">​</a></h3><p><strong>Heading</strong><br> Self explanatory!</p><p>**Next trading plan review date<br> **Insert the date for your next trading plan review. As mentioned, I recommend initially reviewing your plan on a monthly basis, extending to quarterly and then biannually or annually as your consistency and profitability improve.</p><p>**Emergency contacts<br> **Enter contact details for your broker, including account numbers and account names and any other relevant details (NOT PASSWORDS). When something goes wrong and you need to contact your broker immediately, you’ll be happy that you took the time to include these details on the FRONT PAGE of your trading plan. It will also be included on the front page of your Procedures Manual (<a href="/sk/trading-with-pav/procedures-manual/">article 81</a>).</p><h3 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h3><p><strong>Aim</strong><br> Enter a statement describing the aim of the trading plan document. Something like, “This plan is intended to document the <strong>general principles and strategies</strong> that will allow me to produce income from the <strong>____________</strong> markets. It provides the foundation for the Procedures Manual, which details all information for day to day implementation of this plan.”</p><p>**Table of Contents<br> **Self explanatory!</p><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p>**Mission Statement<br> **One or two paragraphs briefly outlining:</p><ul><li>Why are you trading?</li><li>What are you trying to achieve?</li></ul><p>Here I recommend documenting your “reasons why”, which we discovered when discussing the trading psych prerequisites in <a href="/sk/trading-with-pav/personal-survival/#motivation-to-take-positive-action">article 74</a>.</p><p><strong>Goals</strong></p><p><strong>Business Goals</strong> – document your target win% and WLSR, or your 70/90/100 plan, as discussed in <a href="/sk/trading-with-pav/goals-targets/">article 73</a>.</p><p><strong>Daily Goals</strong> – include a note on the importance of process goals rather than outcome goals, during the heat of daily trading battle. Daily goals must not include any outcome or level of performance.</p><h3 id="the-trader" tabindex="-1">The Trader <a class="header-anchor" href="#the-trader" aria-label="Permalink to &quot;The Trader&quot;">​</a></h3><p><strong>Responsibility</strong><br> A statement of personal responsibility!</p><p>For example, “I alone am responsible for all trading outcomes. My success or failure is a result of my own decisions and actions. I therefore trade with a focus on managing risk. My number one goal each day is to ensure I survive to trade another day. Only I can ensure that occurs.”</p><p>**Current State<br> **Successful trading requires an understanding and acceptance of our current strengths and weaknesses, in order to maximise our strengths and overcome or minimise the impact of our weaknesses.</p><p>List your current trading strengths and weaknesses, and your plan for managing these.</p><p><strong>Health</strong><br> Successful trading requires a healthy mind and body. It’s essential to manage your personal health and to ensure a healthy work/life balance.</p><p>Outline how you will achieve this under three sub-sections:</p><ul><li>Mind <ul><li>“I will achieve a healthy mind through the following means:”</li></ul></li><li>Body <ul><li>“I will achieve a healthy body through the following means:”</li></ul></li><li>Social <ul><li>“I will achieve a healthy work/life balance through the following means:”</li></ul></li></ul><p><strong>Further Education</strong><br> Consistent trading success requires ongoing education and growth.</p><ul><li>Outline your plan for further education.</li><li>What will you currently work on? When? How often?</li></ul><h3 id="the-trading-business" tabindex="-1">The Trading Business <a class="header-anchor" href="#the-trading-business" aria-label="Permalink to &quot;The Trading Business&quot;">​</a></h3><p>**Business Management<br> **Outline your plans for the following:</p><ul><li>Tax or Business Structure</li><li>Accounting / Business Software</li><li>Advisors (i.e. accountant, bookkeeper etc.)</li></ul><p><strong>Capital Management</strong></p><ul><li>What funds have you allocated to your trading venture?</li><li>Where are they located?</li><li>What is your maximum loss limit?</li><li>What is your reinvestment plan?</li><li>What is your plan for further contributions to your account equity, if any?</li><li>What is your plan for withdrawal of funds from your account equity?</li></ul><p>**Resource Management<br> **List the trading resources you will use in your business, under the following headings:</p><ul><li>Broker</li><li>Charting</li><li>Data Providers</li><li>Journals <ul><li><a href="/sk/trading-with-pav/additional-documentation/">Article 89</a> will discuss the various logs and journals used in our business.</li><li>List them here, along with a sentence describing their purpose: <ul><li>Trading Log</li><li>Trading Journal Spreadsheet</li><li>Trades Journal</li><li>Market Structure Journal</li><li>Lessons Learnt Journal</li><li>Motivational Journal</li></ul></li></ul></li><li>Economic Calendar <ul><li>The economic calendar I use will be kept updated on the YSTC Resources Page, in the section, “Business Management:”</li><li><a href="/sk/resources.html">https://www.ystc.com/resources</a></li></ul></li><li>Education Resources</li><li>Additional Tools <ul><li>Timers, screen-capture software etc.?</li></ul></li></ul><p>That’s all I list. Your business may require additional resources such as:</p><ul><li>News Sources</li><li>Earnings Calendar</li><li>Market Scan</li><li>Back Testing Software</li><li>Portfolio Management</li><li>Instant Messaging</li></ul><p>**Operations Management<br> **This will simply reference the Procedures Manual. For example:</p><ul><li>The Procedures Manual is to detail daily routines, including all pre-session, during session and post-session routines.</li><li>The Procedures Manual is to detail the recording of trade and trade session stats, within both the Trading Log and Trading Journal Spreadsheet.</li><li>The Procedures Manual is to detail a daily review process, for the purposes of personal growth and development.</li></ul><p>**Contingency Management<br> **Once again, the trading plan will simply reference the Procedures Manual. For example:</p><ul><li>The Procedures Manual is to detail plans for dealing with any contingency which may occur during the trading session.</li></ul><p>**Review Process<br> **When will you conduct reviews? How will you do it?</p><ul><li>Daily <ul><li>Market Structure Review</li><li>Setups / Trades Review</li><li>Personal Performance Review</li></ul></li><li>Weekly <ul><li>Trading Performance Review</li><li>Trading Log Review</li><li>Personal Performance Review</li></ul></li><li>Monthly <ul><li>Trading Performance Review</li><li>Journals Review</li><li>Trading Plan Review</li></ul></li><li>Biannual / Annual <ul><li>Goals Review</li></ul></li></ul><p>Reference the Procedures Manual for review procedures.</p><p>**Time Management<br> **Outline the time that you can commit to your trading business and your ongoing education.</p><ul><li>What time can you allocate for trading (including pre and post-session procedures)?</li><li>What time can you allocate for your weekly, monthly and longer reviews?</li></ul><h3 id="the-trading-process" tabindex="-1">The Trading Process <a class="header-anchor" href="#the-trading-process" aria-label="Permalink to &quot;The Trading Process&quot;">​</a></h3><p><strong>Overview</strong><br> Provide a short overview of your approach to trading. For example:</p><ul><li>I will be trading the YSTC Price Action Strategy, with the following amendments: <ul><li>For the current month I am limiting myself to with Volume Accumulation and Trend Setup only, due to…(reason)</li></ul></li></ul><p><strong>Market &amp; Timeframe Selection</strong></p><ul><li>Which markets are you trading? Why?</li><li>Which timeframes are you trading? Why?</li></ul><p><strong>Market Analysis</strong> I include here a simple reminder of the importance of price action, and then a reference to the Procedures Manual.</p><p>For example:</p><ul><li>Market analysis is to be conducted with a primary emphasis on price action. All indicators are a derivate of price and lag, and shall therefore be considered as decision support tools only.</li><li>The Procedures Manual is to contain a step by step process for conducting market analysis.</li></ul><p><strong>Roles and Responsibilities</strong> Optional section – I don’t use it anymore, but did once with great effect. We’ll talk more about this in <a href="/sk/trading-with-pav/challenges-and-difficulties/#employ-a-team-of-traders">article 96</a> “employ a team of traders”, when discussing challenges and difficulties.</p><ul><li>In order to minimize the negative psychological impact of “being a trader who tries to make a profit“, I will not trade as a trader.</li><li>Instead I will assume the following roles at various times within my trading business: <ul><li>Market Analyst,</li><li>Order Entry Clerk,</li><li>Risk Manager,</li><li>Operations Manager,</li><li>Trading Coach, and</li><li>Compliance Officer.</li></ul></li><li>The Procedures Manual is to assign an appropriate role to each procedural step.</li></ul><p>If using this, then you’ll need to update the procedures manual to assign the appropriate role to each procedural step. I also recommend including a short job-description for each role within the trading plan.</p><p><strong>Risk and Money Management</strong></p><ul><li>Risk management – every trade entered in the market MUST have an attached stop loss order.</li><li>Money management – include notes as discussed in <a href="/sk/trading-with-pav/money-management-explanatory-notes/">article 71</a>.</li></ul><p><strong>Psychology</strong><br> For me, this section simply references the Procedures Manual:</p><ul><li>The Procedures Manual is to outline routines designed to manage emotions and trade with focus, consistency and discipline.</li><li>This will include a plan for relaxation, a plan for clearing my mind and regaining focus following a trade, and a plan for recovery following any negative occurrence such as a significant error or loss, as detailed in <a href="/sk/trading-with-pav/mastery-of-trading-psychology/#recovery-procedure">article 75</a>.</li></ul><p><strong>Trade Strategy</strong><em>NOTE: This section may be duplicated within your trading plan, once per strategy, to cater for those of you who trade multiple strategies.</em></p><p>Describe your trading strategy. This is a chance for you to summaries the YSTC Price Action Trader strategy.</p><p>It may be as simple as referring to the summaries I’ve provided in <a href="/sk/trading-with-pav/summary-trading-with-pav/">article 100</a>.</p><p>However, great benefit will be gained through putting all you’ve read into your own summary words and diagrams.</p><p>You may wish to do so under several headings:</p><ul><li>Principles</li><li>Screen Setup</li><li>Position Sizing</li><li>Analysis</li><li>Setups – Description &amp; Diagram</li><li>Trade Entry</li><li>Trade Management and Exit</li></ul><p><strong>Further Development</strong> List areas of focus for further development of yourself and your trading strategy.</p><h3 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to &quot;Annexes&quot;">​</a></h3><p>Add anything else you wish to add!!!</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',70)),i(t,null,{default:u(()=>[i(n)]),_:1})])}const v=r(d,[["render",c]]);export{w as __pageData,v as default};
